// Generated by the Salvo compiler: the array subscript.
package salvo

// [col-index-trap] [kt-index-trap] A subscript out of range is Salvo's trap,
// not the host's: `xs[i]` on an array is `xs[salvoIx(i, xs.size, at)]`, which
// throws `salvo: index out of range at <module>:<line>:<col>` — the text the
// Rust `SalvoIx` panics with [assert-trap] — instead of the JVM's
// `ArrayIndexOutOfBoundsException`. The array is a place, so reading its size
// a second time evaluates nothing.
fun salvoIx(i: Int, size: Int, at: String): Int {
    if (i < 0 || i >= size) throw AssertionError("salvo: index out of range at $at")
    return i
}
